#include <zephyr/syscall_handler.h>

/* Custom syscall handler for can_get_state to correctly handle NULL pointers.
 * The auto-generated syscall handler does not check for NULL pointers before
 * validating memory access, leading to a segmentation fault when NULL is passed
 * for optional arguments.
 */
Z_SYSCALL_HANDLER(can_get_state, ret, dev, state, err_cnt)
{
	Z_OOPS(Z_SYSCALL_DRIVER_CAN(dev, get_state));

	if (state != NULL) {
		Z_OOPS(z_user_from_nl_may_write(state, sizeof(*state)));
	}
	if (err_cnt != NULL) {
		Z_OOPS(z_user_from_nl_may_write(err_cnt, sizeof(*err_cnt)));
	}

	ret = z_impl_can_get_state(dev, state, err_cnt);
	return ret;
}

